/* Aurora protocol extensions used by Wine's winewayland.drv, Xwayland and toolkit clients:
 *   wp_viewporter v1, zwp_pointer_constraints_v1 v1, zwp_relative_pointer_manager_v1 v1,
 *   zxdg_output_manager_v1 v3, zxdg_decoration_manager_v1 v1.
 * Protocol objects live here; surface state, composition and input stay in desktop.c, which provides
 * the aurora_host_* services below. Bindings are generated by wayland-scanner (desktop.py prepare_protocols). */
#ifndef AURORA_PROTOCOLS_H
#define AURORA_PROTOCOLS_H
#include <stdbool.h>
#include <stdint.h>
#include <wayland-server.h>
struct rectangle;   /* aurora_damage.h: wl_region contents */

/* Double-buffered wp_viewport state (surface-local units; wl_fixed source, integer destination). */
struct aurora_viewport_state { bool source, destination; wl_fixed_t x, y, w, h; int32_t dw, dh; };
enum aurora_constraint_kind { AURORA_CONSTRAINT_NONE, AURORA_CONSTRAINT_LOCK, AURORA_CONSTRAINT_CONFINE };

/* ---- services implemented by desktop.c ---- */
/* Pending viewport state of a wl_surface and its owning wp_viewport slot; NULL when the resource is no Aurora surface. */
struct aurora_viewport_state* aurora_host_viewport(struct wl_resource* surface, struct wl_resource*** owner);
const struct rectangle* aurora_host_region(struct wl_resource* region);     /* wl_region rectangles (add/subtract list) */
bool aurora_host_toplevel_configured(struct wl_resource* toplevel);         /* initial configure already sent */
bool aurora_host_toplevel_has_buffer(struct wl_resource* toplevel);
void aurora_host_toplevel_configure(struct wl_resource* toplevel);          /* send a fresh xdg_surface.configure */
void aurora_host_output_size(int32_t* width, int32_t* height);
/* Logical rectangle, name and description of the display a wl_output resource stands for (false: gone). */
bool aurora_host_output_info(struct wl_resource* output, int32_t* x, int32_t* y, int32_t* width, int32_t* height, char* name, char* description, size_t size);
void aurora_host_constraints_changed(void);                                 /* re-evaluate constraint activation */
int aurora_host_surface_scale(struct wl_resource* surface);                 /* preferred scale (1/120) of a wl_surface; 0: not ours */
/* xdg_activation_v1.activate with a valid token: raise/focus (and unminimize) surface's window if the policy allows.
 * requester: the client that obtained the token; focused: it had keyboard focus when it committed the token. */
void aurora_host_activation(struct wl_resource* surface, struct wl_client* requester, bool focused);
bool aurora_host_client_focused(struct wl_client* client);

/* ---- entry points for desktop.c ---- */
bool aurora_protocols_init(struct wl_display* display);
/* wp_fractional_scale_v1 (v1): the preferred scale (1/120) of wl_surface surface may have changed (sent when it did). */
void aurora_protocols_preferred_scale(struct wl_resource* surface, int scale120);
/* A display changed (layout, mode, scale): fresh zxdg_output_v1 state of wl_output resource output, sent before its
 * wl_output events and done. */
void aurora_protocols_output_changed(struct wl_resource* output);
/* zwp_relative_pointer_v1.relative_motion to every relative pointer of client (wl_pointer.frame follows from the caller). */
bool aurora_relative_motion(struct wl_client* client, uint64_t usec, wl_fixed_t dx, wl_fixed_t dy);
/* Apply pending constraint regions and position hints of surface (wl_surface.commit). */
void aurora_constraints_commit(struct wl_resource* surface);
/* Activate the constraint of surface (the pointer focus, pointer at x,y surface-local) when focused and inside its
 * region; deactivate any other. surface NULL deactivates all. Returns the active kind. */
enum aurora_constraint_kind aurora_constraints_update(struct wl_resource* surface, int32_t x, int32_t y, bool focused);
/* For the active confinement: whether x,y (surface-local) lies inside its region. */
bool aurora_constraint_contains(int32_t x, int32_t y);
/* The active confinement's region (add/subtract list); NULL when it is infinite or no confinement is active. */
const struct rectangle* aurora_constraint_region(void);
/* After a lock ended: its cursor position hint (surface-local), once. */
bool aurora_constraint_take_hint(struct wl_resource** surface, wl_fixed_t* x, wl_fixed_t* y);
bool aurora_region_contains(const struct rectangle* region, int64_t x, int64_t y);
#endif
